(window.WSR_PARTS = window.WSR_PARTS || {})["ved-rundarne-1864"] = {"title": "Ved Rundarne (1864)", "lang": "nn", "html": "<section><div><p><span class=\"wsr-page\" data-num=\"161\" data-page-title=\"Side:Vinje-Diktsamling.djvu/177\"></span></p><div class=\"wsr-verse\"><div class=\"wsr-stanza\"><span class=\"wsr-line\" data-n=\"1\">No seer eg atter slike Fjell og Dalar,</span>\n<span class=\"wsr-line\" data-n=\"2\">som deim eg i min fyrste Ungdom saag,</span>\n<span class=\"wsr-line\" data-n=\"3\">og sama Vind den heite Panna svalar;</span>\n<span class=\"wsr-line\" data-n=\"4\">og Gullet ligg paa Snjo, som før det laag.</span>\n<span class=\"wsr-line\" data-n=\"5\">Det er eit Barnemaal, som til meg talar,</span>\n<span class=\"wsr-line\" data-n=\"6\">og gjer meg tankefull, men endaa fjaag.</span>\n<span class=\"wsr-line\" data-n=\"7\">Med Ungdomsminne er den Tala blandad:</span>\n<span class=\"wsr-line\" data-n=\"8\">det strøymer paa meg, so eg knapt kan anda.</span></div>\n<div class=\"wsr-stanza\"><span class=\"wsr-line\" data-n=\"9\">Ja, Livet strøymer paa meg, som det strøymde,</span>\n<span class=\"wsr-line\" data-n=\"10\">naar under Snjo eg saag det grøne Straa.</span>\n<span class=\"wsr-line\" data-n=\"11\">Eg drøymer no, som før eg altid drøymde,</span>\n<span class=\"wsr-line\" data-n=\"12\">naar slike Fjell eg saag i Lufti blaa.</span>\n<span class=\"wsr-line\" data-n=\"13\">Eg gløymer Dagsens Strid, som før eg gløymde,</span>\n<span class=\"wsr-line\" data-n=\"14\">naar eg mot Kveld av Sol eit Glimt fekk sjaa.</span>\n<span class=\"wsr-line\" data-n=\"15\">Eg finner vel eit Hus, som vil meg hysa,</span>\n<span class=\"wsr-line\" data-n=\"16\">naar Soli heim til Notti vil meg lysa.</span></div>\n<div class=\"wsr-stanza\"><span class=\"wsr-line\" data-n=\"17\">Alt er som før, men det er meir forklaarat,</span>\n<span class=\"wsr-line\" data-n=\"18\">so Dagsens Ljos meg synes meire bjart,</span>\n<span class=\"wsr-line\" data-n=\"19\">og det, som beit og skar meg, so det saarat,</span>\n<span class=\"wsr-line\" data-n=\"20\">det gjerer sjølve Skuggen mindre svart;</span>\n<span class=\"wsr-line\" data-n=\"21\">sjølv det, som til at synda tidt meg daarat,</span>\n<span class=\"wsr-line\" data-n=\"22\">sjølv det gjer harde Fjellet mindre hardt.</span>\n<span class=\"wsr-line\" data-n=\"23\">Forsonad’ koma atter gamle Tankar;</span>\n<span class=\"wsr-line\" data-n=\"24\">det sama Hjarta er, som eldre bankar.</span></div></div><p> <span class=\"wsr-page\" data-num=\"162\" data-page-title=\"Side:Vinje-Diktsamling.djvu/178\"></span></p><div class=\"wsr-verse\"><div class=\"wsr-stanza\"><span class=\"wsr-line\" data-n=\"1\">Og hver ein Stein eg som ein Kjenning finner,</span>\n<span class=\"wsr-line\" data-n=\"2\">for slik var den, eg flaug ikring som Gut.</span>\n<span class=\"wsr-line\" data-n=\"3\">som det var Kjempur, spyr eg, hvem som vinner</span>\n<span class=\"wsr-line\" data-n=\"4\">av den og denne andre haage Nut.</span>\n<span class=\"wsr-line\" data-n=\"5\">Alt minner meg; det minner, og det minner,</span>\n<span class=\"wsr-line\" data-n=\"6\">til Soli burt i Snjoen sloknar ut.</span>\n<span class=\"wsr-line\" data-n=\"7\">Og inn i siste Svevn meg eingong huggar</span>\n<span class=\"wsr-line\" data-n=\"8\">dei gamle Minne og dei gamle Skuggar.</span></div></div></div>\n</section>"};
